export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;
  scene.clearColor = new BABYLON.Color4(0.48, 0.55, 0.41);

  var camera = new BABYLON.FreeCamera("camera", new BABYLON.Vector3(0, 12, 0), scene);
  camera.rotation.x = Math.PI / 2 + Math.PI / 2900;
  camera.rotation.y = Math.PI;
  // camera.attachControl();

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  var ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 12, height: 8 }, scene);
  // ground.rotation.x = -Math.PI / 2;

  var dirLight = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(-0.63, -0.7, -0.77), scene);
  dirLight.position = new BABYLON.Vector3(-6.14, 24, 46.37);
  dirLight.diffuse = BABYLON.Color3.FromHexString("#FFF8E3");
  dirLight.intensity = 1.5;
  dirLight.shadowMaxZ = 300;

  let darkness = -1;

  let shadowGenerator_D = new BABYLON.CascadedShadowGenerator(1024, dirLight);
  shadowGenerator_D.autoCalcDepthBounds = true;
  shadowGenerator_D.lambda = 1;
  shadowGenerator_D.bias = 0.001;
  shadowGenerator_D._darkness = darkness;

  var texture = new BABYLON.DynamicTexture("dynamic texture", { width: 512, height: 512 }, scene, true);
  var material = new BABYLON.PBRMaterial("mat", scene);
  material.albedoTexture = texture;
  material.metallic = 0;
  material.roughness = 1;
  // material.unlit = true;
  ground.material = material;
  ground.receiveShadows = true;

  let azimuth = 316;
  let elevation = 316;

  const updateLightDirection = (azimuthValue, elevationValue) => {
    if (dirLight) {
      if (elevationValue <= 181) {
        elevationValue = 181;
      } else if (elevationValue >= 359) {
        elevationValue = 359;
      }
      const azimuthRad = BABYLON.Tools.ToRadians(azimuthValue);
      const elevationRad = BABYLON.Tools.ToRadians(elevationValue);

      const x = Math.cos(elevationRad) * Math.sin(azimuthRad);
      const y = Math.sin(elevationRad);
      const z = Math.cos(elevationRad) * Math.cos(azimuthRad);

      dirLight.direction = new BABYLON.Vector3(x, y, z).normalize();
    }
  };

  updateLightDirection(azimuth, elevation);

  var context = texture.getContext();
  var backgroundImage = new Image();
  var backgroundLoaded = false;

  backgroundImage.crossOrigin = "anonymous";

  var proxyUrl = "https://api.allorigins.win/raw?url=";
  var testUrl =
    "https://images.unsplash.com/photo-1625212895824-ff2232e9f304?q=80&w=2071&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D";

  var loadingText = new BABYLON.GUI.TextBlock();
  loadingText.text = "Loading...";
  loadingText.color = "white";
  loadingText.fontSize = 24;
  loadingText.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
  loadingText.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");
  advancedTexture.addControl(loadingText);

  const getBase64FromUrl = async (url) => {
    const data = await fetch(proxyUrl + encodeURIComponent(url));
    const blob = await data.blob();
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.readAsDataURL(blob);
      reader.onloadend = function () {
        resolve(reader.result);
      };
    });
  };

  let pencil;

  getBase64FromUrl(testUrl).then((a) => {
    backgroundImage.src = a;

    BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "pencil.glb").then((result) => {
      pencil = result.meshes[0];
      pencil.normalizeToUnitCube(true);
      pencil.name = "Pencil";
      pencil.rotation.y = Math.PI;
      pencil.position.y = 1;

      pencil.getChildTransformNodes(true)[0].position.x = 1.5;
      pencil.getChildTransformNodes(true)[0].position.y = -2;

      // document.body.style.cursor = 'none';
      pencil.getChildMeshes().forEach((mesh) => {
        shadowGenerator_D.addShadowCaster(mesh);
        mesh.receiveShadows = true;
      });

      dirLight.getShadowGenerator().getShadowMap().resize(1024);
      dirLight.getShadowGenerator().getShadowMap().scale(Math.pow(2, 2));
    });
  });

  backgroundImage.onload = function () {
    context.clearRect(0, 0, 512, 512);
    context.save();
    context.translate(512, 0); // 캔버스를 X축 방향으로 512px 이동
    context.scale(-1, 1); // 좌우 반전
    context.drawImage(backgroundImage, 0, 0, 512, 512);
    context.restore();

    texture.update();
    backgroundLoaded = true;

    loadingText.isVisible = false; // 로딩 화면 숨기기
  };

  var isMoved = false;
  var isLeftClicked = false;
  var lastX = 0,
    lastY = 0;
  var penColor = "#ff0000";
  var penWidth = 5;
  var brushType = "pencil";

  var history = [];
  var maxHistory = 20;
  var isDrawing = false;

  function saveCanvasState() {
    if (history.length >= maxHistory) {
      history.shift();
    }
    history.push(context.getImageData(0, 0, 512, 512));
  }

  function undoLastStroke() {
    if (history.length > 0) {
      let previousState = history.pop();
      if (previousState) {
        context.putImageData(previousState, 0, 0);
        if (texture._texture) {
          texture.update();
        }
      }
    }
  }

  var minDistance = 3; // 손떨림 보정 거리
  var isDebugging = false;

  function drawOnTexture(x, y) {
    if (!backgroundLoaded) return;

    var distance = Math.sqrt((x - lastX) ** 2 + (y - lastY) ** 2);

    if (distance < minDistance) {
      return;
    }

    var steps = Math.ceil(distance / minDistance);

    if (brushType === "pencil") {
      for (let i = 1; i <= steps; i++) {
        let lerpX = lastX + (x - lastX) * (i / steps);
        let lerpY = lastY + (y - lastY) * (i / steps);

        context.beginPath();
        context.moveTo(lastX, lastY);
        context.lineTo(lerpX, lerpY);
        context.strokeStyle = penColor;
        context.lineWidth = penWidth;
        context.lineCap = "round";
        context.stroke();
        context.closePath();

        if (isDebugging) {
          context.beginPath();
          context.arc(lerpX, lerpY, 2, 0, Math.PI * 2);
          context.fillStyle = "blue";
          context.fill();
          context.closePath();
        }

        lastX = lerpX;
        lastY = lerpY;
      }
    } else if (brushType === "smudge") {
      applySmudgeEffect(x, y);
    }

    texture.update();
  }

  scene.onPointerDown = function (evt, pickResult) {
    if (pickResult.hit && pickResult.pickedMesh === ground) {
      isLeftClicked = true;
      isDrawing = true;
      saveCanvasState();
      var uv = pickResult.getTextureCoordinates();
      lastX = uv.x * 512;
      lastY = (1 - uv.y) * 512;
    }
  };

  scene.onPointerUp = function () {
    isLeftClicked = false;
    isDrawing = false;

    if (pencil) {
      shakePencil(false);
    }
  };

  window.addEventListener("keydown", function (event) {
    if (event.ctrlKey && event.key === "z") {
      undoLastStroke();
    }
  });

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function applySmudgeEffect(x, y) {
    var radius = penWidth * 2;
    var imageData = context.getImageData(x - radius / 2, y - radius / 2, radius, radius);
    var data = imageData.data;

    var smudgeStrength = 0.4;

    for (let i = 0; i < data.length; i += 4) {
      let r = data[i];
      let g = data[i + 1];
      let b = data[i + 2];

      let randomOffset = Math.floor(Math.random() * 4 - 2) * 4;
      let targetIndex = i + randomOffset;

      if (targetIndex >= 0 && targetIndex < data.length) {
        data[i] = lerp(r, data[targetIndex], smudgeStrength);
        data[i + 1] = lerp(g, data[targetIndex + 1], smudgeStrength);
        data[i + 2] = lerp(b, data[targetIndex + 2], smudgeStrength);
      }
    }

    context.putImageData(imageData, x - radius / 2, y - radius / 2);
  }

  function applySmudgeToWholeCanvas() {
    var imageData = context.getImageData(0, 0, 512, 512);
    var data = imageData.data;
    var smudgeStrength = 0.8;

    for (let i = 0; i < data.length; i += 4) {
      let r = data[i];
      let g = data[i + 1];
      let b = data[i + 2];

      let randomOffset = Math.floor(Math.random() * 8 - 4) * 4;
      let targetIndex = i + randomOffset;

      if (targetIndex >= 0 && targetIndex < data.length) {
        data[i] = lerp(r, data[targetIndex], smudgeStrength);
        data[i + 1] = lerp(g, data[targetIndex + 1], smudgeStrength);
        data[i + 2] = lerp(b, data[targetIndex + 2], smudgeStrength);
      }
    }

    context.putImageData(imageData, 0, 0);
    texture.update();
  }

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  var moveTimeout;

  scene.onPointerMove = function (evt) {
    if (pencil) {
      var pickResult = scene.pick(scene.pointerX, scene.pointerY);
      if (pickResult.hit) {
        isMoved = true;
        var point = pickResult.pickedPoint;
        if (point) {
          pencil.position.copyFrom(point);
          pencil.position.y += 0.5;
        }
        document.body.style.cursor = "none";
      } else {
        document.body.style.cursor = "default";
      }
    }

    if (isLeftClicked) {
      var pickResult = scene.pick(scene.pointerX, scene.pointerY);
      if (pickResult.hit && pickResult.pickedMesh === ground) {
        isMoved = true;
        var uv = pickResult.getTextureCoordinates();
        var x = uv.x * 512;
        var y = (1 - uv.y) * 512;
        drawOnTexture(x, y);
      }
    }

    clearTimeout(moveTimeout);
    moveTimeout = setTimeout(function () {
      isMoved = false;
      shakePencil(false);
    }, 500);
  };

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  var colorPicker = new BABYLON.GUI.ColorPicker();
  colorPicker.width = "150px";
  colorPicker.height = "150px";
  colorPicker.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  colorPicker.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  colorPicker.left = "20px";
  colorPicker.top = "20px";
  colorPicker.onValueChangedObservable.add(function (value) {
    penColor = `rgb(${Math.floor(value.r * 255)}, ${Math.floor(value.g * 255)}, ${Math.floor(value.b * 255)})`;
  });
  advancedTexture.addControl(colorPicker);

  var slider = new BABYLON.GUI.Slider();
  slider.minimum = 1;
  slider.maximum = 20;
  slider.value = 5;
  slider.height = "20px";
  slider.width = "200px";
  slider.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  slider.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  slider.left = "20px";
  slider.top = "200px";
  slider.onValueChangedObservable.add(function (value) {
    penWidth = value;
  });
  advancedTexture.addControl(slider);

  var brushButton = BABYLON.GUI.Button.CreateSimpleButton("brushButton", "Toggle Brush");
  brushButton.width = "150px";
  brushButton.height = "40px";
  brushButton.color = "white";
  brushButton.background = "blue";
  brushButton.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  brushButton.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  brushButton.left = "20px";
  brushButton.top = "300px";
  brushButton.onPointerClickObservable.add(() => {
    brushType = brushType === "pencil" ? "smudge" : "pencil";
    brushButton.textBlock.text = brushType === "pencil" ? "Brush: Pencil" : "Brush: Smudge";
  });
  advancedTexture.addControl(brushButton);

  var smudgeButton = BABYLON.GUI.Button.CreateSimpleButton("smudgeBtn", "Apply Smudge");
  smudgeButton.width = "150px";
  smudgeButton.height = "40px";
  smudgeButton.color = "white";
  smudgeButton.background = "blue";
  smudgeButton.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
  smudgeButton.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_BOTTOM;
  smudgeButton.top = "-50px";
  smudgeButton.onPointerClickObservable.add(() => {
    applySmudgeToWholeCanvas();
  });
  advancedTexture.addControl(smudgeButton);

  scene.registerBeforeRender(() => {
    if (pencil && isMoved && isLeftClicked) {
      shakePencil(true);
    } else {
      shakePencil(false);
    }
  });

  var shakeAnim;
  var isShaking = false;

  function shakePencil(start) {
    if (!pencil) return;

    if (start) {
      if (isShaking) return;
      isShaking = true;

      if (!shakeAnim) {
        shakeAnim = new BABYLON.Animation(
          "shake",
          "rotation.z",
          60,
          BABYLON.Animation.ANIMATIONTYPE_FLOAT,
          BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
        );

        var keys = [];
        keys.push({ frame: 0, value: 0 });
        keys.push({ frame: 10, value: 0.1 });
        keys.push({ frame: 20, value: -0.1 });
        keys.push({ frame: 30, value: 0.1 });
        keys.push({ frame: 40, value: -0.1 });
        keys.push({ frame: 50, value: 0 });

        shakeAnim.setKeys(keys);
        pencil.animations = [shakeAnim];
      }

      scene.beginAnimation(pencil, 0, 50, true);
    } else {
      if (!isShaking) return;
      isShaking = false;

      scene.stopAnimation(pencil);
      pencil.rotation.z = 0;
    }
  }

  return scene;
}
